package cz.systematic.money;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.widget.RemoteViews;import org.json.*;import java.util.*;import java.util.concurrent.*;
public class MoneyWidget extends AppWidgetProvider {
 static final ExecutorService executor=Executors.newSingleThreadExecutor();static final String REFRESH="cz.systematic.money.REFRESH_WIDGET",SAVE="cz.systematic.money.SAVE_WIDGET";
 public static void refreshAll(Context c){int[] ids=AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,MoneyWidget.class));for(int id:ids)executor.execute(()->update(c,id,true));}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){final PendingResult pending=goAsync();executor.execute(()->{try{for(int id:ids)update(c,id,false);}finally{pending.finish();}});}
 @Override public void onDeleted(Context c,int[] ids){for(int id:ids)WidgetStore.prefs(c).edit().remove("action_"+id).remove("nonce_"+id).remove("saved_"+id).remove("pending_"+id).apply();}
 @Override public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(!REFRESH.equals(intent.getAction())&&!SAVE.equals(intent.getAction()))return;int id=intent.getIntExtra("widgetId",-1);if(id<0)return;PendingResult pending=goAsync();executor.execute(()->{try{if(REFRESH.equals(intent.getAction())){update(c,id,true);return;}KeyguardManager lock=(KeyguardManager)c.getSystemService(Context.KEYGUARD_SERVICE);if(lock.isDeviceLocked()){render(c,id,null,"Odemkněte telefon",false);return;}String action=intent.getStringExtra("actionId"),nonce=intent.getStringExtra("requestId");WidgetStore.prefs(c).edit().putBoolean("pending_"+id,true).commit();JSONObject result=WidgetAPI.request(c,"/actions/"+action,new JSONObject().put("requestId",nonce));if(result.optBoolean("ok")){WidgetStore.prefs(c).edit().putBoolean("pending_"+id,false).putBoolean("saved_"+id,true).commit();update(c,id,false);}}catch(Exception e){failure(c,id);}finally{pending.finish();}});}
 static void update(Context c,int id,boolean reset){try{if(reset&&!WidgetStore.prefs(c).getBoolean("pending_"+id,false))WidgetStore.prefs(c).edit().putString("nonce_"+id,UUID.randomUUID().toString()).putBoolean("saved_"+id,false).commit();JSONObject snapshot=WidgetAPI.request(c,"/snapshot",null);render(c,id,snapshot,WidgetStore.prefs(c).getBoolean("saved_"+id,false)?"Uloženo · obnovte pro další platbu":"Aktualizováno "+new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),true);}catch(Exception e){failure(c,id);}}
 static void failure(Context c,int id){try{WidgetStore.read(c);RemoteViews partial=new RemoteViews(c.getPackageName(),R.layout.money_widget);partial.setTextViewText(R.id.widget_status,"Výsledek neověřený · opakujte stejnou akci");AppWidgetManager.getInstance(c).partiallyUpdateAppWidget(id,partial);}catch(Exception e){render(c,id,null,"Připojte widgety v aplikaci",false);}}
 static String money(String cents){try{return new java.math.BigDecimal(cents).movePointLeft(2).setScale(2).toPlainString()+" Kč";}catch(Exception e){return "••••";}}
 static void render(Context c,int id,JSONObject snapshot,String message,boolean online){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.money_widget);String selected=WidgetStore.prefs(c).getString("action_"+id,"");JSONObject action=null;if(snapshot!=null){JSONArray actions=snapshot.optJSONArray("actions");if(actions!=null)for(int n=0;n<actions.length();n++){JSONObject a=actions.optJSONObject(n);if(a.optString("id").equals(selected)){action=a;break;}}}boolean locked=((KeyguardManager)c.getSystemService(Context.KEYGUARD_SERVICE)).isDeviceLocked();v.setTextViewText(R.id.widget_balance,snapshot!=null&&!locked&&action!=null&&action.optBoolean("showBalance")&&!snapshot.isNull("balance")?money(snapshot.optString("balance")):"SYSTEMATIC MONEY");v.setTextViewText(R.id.widget_status,message);v.setTextViewText(R.id.quick_expense,action==null?"Vybrat rychlou akci":action.optString("name")+" · "+money(action.optString("amount")));
 Intent refresh=new Intent(c,MoneyWidget.class).setAction(REFRESH).putExtra("widgetId",id).setData(Uri.parse("moneywidget://refresh/"+id));v.setOnClickPendingIntent(R.id.widget_refresh,PendingIntent.getBroadcast(c,id,refresh,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
 Intent settings=new Intent(c,WidgetConfigActivity.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);v.setOnClickPendingIntent(R.id.widget_settings,PendingIntent.getActivity(c,id,settings,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
 if(action==null){v.setOnClickPendingIntent(R.id.quick_expense,PendingIntent.getActivity(c,id,settings,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}else if(action.optString("mode").equals("DIRECT")&&!locked){String nonce=WidgetStore.prefs(c).getString("nonce_"+id,null);if(nonce==null){nonce=UUID.randomUUID().toString();WidgetStore.prefs(c).edit().putString("nonce_"+id,nonce).commit();}Intent save=new Intent(c,MoneyWidget.class).setAction(SAVE).setData(Uri.parse("moneywidget://save/"+id+"/"+nonce)).putExtra("widgetId",id).putExtra("actionId",action.optString("id")).putExtra("requestId",nonce);v.setOnClickPendingIntent(R.id.quick_expense,PendingIntent.getBroadcast(c,id,save,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));}else{Intent open=new Intent(c,MainActivity.class).setAction(Intent.ACTION_VIEW).setData(Uri.parse("systematicmoney://quick?action="+action.optString("id"))).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);v.setOnClickPendingIntent(R.id.quick_expense,PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}AppWidgetManager.getInstance(c).updateAppWidget(id,v);}
}
